module Maybe =
  let bind m f =
    match m:
      case Some x: f x
      case None: None
  let return_ x = Some x
let safeDiv a b =
  Maybe {
    let! x = String.toInt a
    let! y = String.toInt b
    let! q = if y == 0 then None else Some (x // y)
    let shown = q * 3
    return shown
  }
