let ping n acc = if n <= 0 then acc else stepB (n - 1) (acc + 1)
let stepB n acc = if n <= 0 then acc else pang (n - 2) (acc * 2)
let pang n acc = if n <= 0 then acc else ping (n - 3) (acc - 1)
print (List.map (fun n -> ping n 1) [17, 15, 15, 5])

