let tally xs =
  let mut evens = 0
  let mut odds = 0
  let visit x =
    let bump isEven =
      if isEven then evens <- evens + x else odds <- odds + 1
    bump (x % 2 == 0)
  List.iter visit xs
  (evens, odds)
